      const bgGrad = ctx.createRadialGradient(w * 0.5, h * 0.42, 12, w * 0.5, h * 0.5, w * 0.68);
      bgGrad.addColorStop(0, '#2c1f4a');
      bgGrad.addColorStop(0.65, '#191330');
