    /** Single-source lantern pillar tile coordinates across every Option D rural fence segment. */
    getRuralOptionDPillars() {
      if (this._ruralOptionDPillarsCache) return this._ruralOptionDPillarsCache;
      const pillars = [];
      for (const seg of this.getRuralOptionDFenceSegments()) {
        const isVert = seg.orient === 'v';
        const spanTiles = isVert ? (seg.y2 - seg.y1) : (seg.x2 - seg.x1);
        if (spanTiles <= 0.2) continue;
        const bayCount = spanTiles < 5.2 ? 1 : Math.max(2, Math.round(spanTiles / 3.8));
        for (let b = 0; b <= bayCount; b++) {
          const t = b / bayCount;
          pillars.push(isVert
            ? { x: seg.x, y: seg.y1 + spanTiles * t }
            : { x: seg.x1 + spanTiles * t, y: seg.y }
          );
        }
      }
      // Meadowland Archway twin post lanterns & Farmhouse 1 / Farmhouse 2 / Haystack Barn front porch lanterns
      pillars.push(
        { x: 13.58, y: -1.10 },
        { x: 16.07, y: -1.10 },
        { x: 23.15, y: -16.80 },
        { x: 24.25, y: -16.80 },
        { x: 41.80, y: -16.80 },
        { x: 43.40, y: -16.80 },
        { x: 46.15, y: -25.40 },
        { x: 48.35, y: -25.40 },
        { x: 18.02, y: -4.40 },
        { x: 21.58, y: -4.40 }
      );
      this._ruralOptionDPillarsCache = pillars;
      return pillars;
    }

    /** Single-source organic Meadowbrook Lake contour test for both rendering & shoreline collision. */
    isInMeadowbrookLake(tx, ty) {
      const cx = 42.25;
      const cy = 3.25;
      const rx = 7.75;
      const ry = 5.25;
      const dx = (tx - cx) / rx;
      const dy = (ty - cy) / ry;
      const dist = Math.hypot(dx, dy);
      if (dist > 1.10) return false;
      const ang = Math.atan2(dy, dx);
      const rMod = 1.0 + 0.06 * Math.sin(ang * 3 + 0.6) + 0.04 * Math.cos(ang * 5 - 0.4);
      return dist <= 0.96 * rMod;
    }

    getMeadowbrookPathLights() {
      if (this._meadowbrookPathLightsCache) return this._meadowbrookPathLightsCache;
      const cx = 42.25;
      const cy = 3.25;
      const rx = 7.75;
      const ry = 5.25;
      const angles = [-2.25, -1.35, -0.45, 0.45, 1.35, 2.05];
      this._meadowbrookPathLightsCache = angles.map((ang) => {
        const rMod = 1.0 + 0.06 * Math.sin(ang * 3 + 0.6) + 0.04 * Math.cos(ang * 5 - 0.4);
        const scale = 1.24 * rMod;
        return {
          x: cx + Math.cos(ang) * rx * scale,
          y: cy + Math.sin(ang) * ry * scale,
        };
      });
      return this._meadowbrookPathLightsCache;
    }

