      pxBox(dkX + 24, dkY + 14, 48, 26, '#fef3c7', '#ffffff', '#d6d3d1', INK, 1.5);
      pxBox(dkX + 94, dkY + 8, 30, 22, '#fbbf24', '#fef08a', '#b45309', INK, 2);

